<?php

namespace Alura\Chat;

use Ratchet\ConnectionInterface;
use Ratchet\RFC6455\Messaging\MessageInterface;
use Ratchet\WebSocket\MessageComponentInterface;
use Ds\Set;

class ChatController implements MessageComponentInterface
{
    private Set $connections;
    private array $authenticatedUsers;

    const PASSWORD = 'senha123';

    public function __construct()
    {
        fwrite(STDOUT, 'Servidor inicializado' . PHP_EOL);
        $this->connections = new Set();
        $this->authenticatedUsers = [];
    }

    function onOpen(ConnectionInterface $conn)
    {
        fwrite(STDOUT, 'Nova conexão aberta: ' . $conn->resourceId . PHP_EOL);
        $this->connections->add($conn);

        // Solicita autenticação ao cliente
        $conn->send(json_encode(['type' => 'auth_request']));
    }

    function onClose(ConnectionInterface $conn)
    {
        fwrite(STDOUT, $conn->resourceId . ' fechando conexão...' . PHP_EOL);
        $this->connections->remove($conn);

        if (($key = array_search($conn->resourceId, $this->authenticatedUsers)) !== false) {
            unset($this->authenticatedUsers[$key]);
        }
    }

    function onError(ConnectionInterface $conn, \Exception $e)
    {
        fwrite(STDERR, sprintf('Erro %s com conexão %d%s', $e->getTraceAsString(), $conn->resourceId, PHP_EOL));
    }

    public function onMessage(ConnectionInterface $from, MessageInterface $msg)
    {
        $data = json_decode($msg->getPayload(), true);

        // Autenticação
        if (isset($data['type']) && $data['type'] === 'authenticate') {
            if (isset($data['password']) && $data['password'] === self::PASSWORD) {
                $this->authenticatedUsers[] = $from->resourceId;
                $from->send(json_encode(['type' => 'auth_success']));
                fwrite(STDOUT, 'Usuário autenticado: ' . $from->resourceId . PHP_EOL);
                return;
            } else {
                $from->send(json_encode(['type' => 'auth_failed']));
                fwrite(STDOUT, 'Falha na autenticação para: ' . $from->resourceId . PHP_EOL);
                return;
            }
        }

        // Mensagens apenas de usuários autenticados
        if (!in_array($from->resourceId, $this->authenticatedUsers)) {
            $from->send(json_encode(['type' => 'not_authenticated']));
            return;
        }

        // Envia mensagem para todos os outros usuários autenticados
        foreach ($this->connections as $connection) {
            if ($connection->resourceId !== $from->resourceId) {
                $connection->send($msg);
            }
        }
    }
}
